using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class RepairCapture{
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_PropRepair/"));
 static int count;
 static void Shot(string n,Transform t,Vector3 at,Vector3 offset,float fov){var go=new GameObject("PropRepair_Review_Temporary");var c=go.AddComponent<Camera>();var target=t.TransformPoint(at);c.transform.position=target+t.TransformDirection(offset);c.transform.LookAt(target);c.nearClipPlane=.02f;c.farClipPlane=180;c.fieldOfView=fov;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.027f,.037f,.05f);c.GetUniversalAdditionalCameraData().renderPostProcessing=false;c.allowMSAA=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());count++;}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");Directory.CreateDirectory(O);count=0;var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var bank=root.Find("C01_Experiment_Art/C01_Perimeter_Lab");var hidden=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToDictionary(r=>r,r=>r.enabled);
 try{foreach(var r in hidden.Keys)r.enabled=false;
 var a=bank.Find("Station_48/CP_OpticalAnalyzer");Shot(prefix+"_OpticalAnalyzer",a,new Vector3(0,.34f,0),new Vector3(.62f,.55f,1.3f),48);Shot(prefix+"_Analyzer_Clearance",a,new Vector3(.27f,.44f,.17f),new Vector3(.25f,.22f,.62f),45);
 var p=bank.GetComponentsInChildren<Transform>().First(t=>t.name=="CP_PreparationKit");Shot(prefix+"_PreparationKit",p,new Vector3(0,.10f,0),new Vector3(.35f,.75f,.75f),53);Shot(prefix+"_Preparation_Tray",p,new Vector3(-.10f,.05f,.17f),new Vector3(.10f,.40f,.45f),48);
 foreach(var n in new[]{"ID_DualVortexMixer","ID_PipetteWorkstation","ID_ChromatographyStack","ID_FlowCytometer","ID_MixedSupplyShelf","ID_SterileSealer","ID_LabelPrinter"}){var t=bank.GetComponentsInChildren<Transform>().First(x=>x.name==n);float y=n.Contains("Shelf")?.40f:n.Contains("Chromatography")?.60f:.27f;Shot(prefix+"_"+n,t,new Vector3(0,y,0),new Vector3(.38f,.45f,1.05f),50);}
 var v=bank.GetComponentsInChildren<Transform>().First(x=>x.name=="ID_DualVortexMixer");Shot(prefix+"_Vial_Detail",v,new Vector3(-.13f,.33f,0),new Vector3(.11f,.08f,.32f),42);
 var cab=root.GetComponentsInChildren<Transform>().First(x=>x.name=="CP_EmergencyCabinet");Shot(prefix+"_EmergencyCabinet",cab,new Vector3(0,.91f,0),new Vector3(.40f,.15f,1.65f),48);
 }finally{foreach(var kv in hidden)kv.Key.enabled=kv.Value;EditorSceneManager.OpenScene(s.path);}return new{prefix,images=count,output=O};}
}
